#pragma once

#include <cstddef>
#include <list>
#include <optional>
#include <string>
#include <string_view>
#include <unordered_map>
#include <utility>

// Fixed-capacity least-recently-used cache with O(1) expected-time operations.
//
// Entries live in a doubly linked list ordered from most to least recently
// used. The index maps keys to list nodes; its string_view keys point into the
// list nodes' own key strings, which stay put because list nodes never move.
class LruCache {
public:
    explicit LruCache(std::size_t capacity) : capacity_(capacity) {
        index_.reserve(capacity + 1);
    }

    // Inserts or overwrites `key`, making it the most recently used entry.
    // Evicts the least recently used entry if capacity is exceeded.
    void set(std::string_view key, std::string_view value) {
        if (auto it = index_.find(key); it != index_.end()) {
            it->second->value.assign(value);
            touch(it->second);
            return;
        }
        entries_.push_front(Entry{std::string(key), std::string(value)});
        index_.emplace(entries_.front().key, entries_.begin());
        if (index_.size() > capacity_) {
            evict_oldest();
        }
    }

    // Returns the value for `key` and marks it most recently used, or
    // std::nullopt on a miss. The view is valid until the next mutation.
    [[nodiscard]] std::optional<std::string_view> get(std::string_view key) {
        auto it = index_.find(key);
        if (it == index_.end()) {
            return std::nullopt;
        }
        touch(it->second);
        return std::string_view(it->second->value);
    }

    // Removes `key`; returns whether it was present.
    bool erase(std::string_view key) {
        auto it = index_.find(key);
        if (it == index_.end()) {
            return false;
        }
        auto node = it->second;
        index_.erase(it);  // erase first: the map key views the node's string
        entries_.erase(node);
        return true;
    }

    [[nodiscard]] std::size_t size() const noexcept { return index_.size(); }
    [[nodiscard]] std::size_t capacity() const noexcept { return capacity_; }

private:
    struct Entry {
        std::string key;
        std::string value;
    };
    using List = std::list<Entry>;

    void touch(List::iterator node) {
        entries_.splice(entries_.begin(), entries_, node);
    }

    void evict_oldest() {
        auto node = std::prev(entries_.end());
        index_.erase(std::string_view(node->key));
        entries_.erase(node);
    }

    std::size_t capacity_;
    List entries_;
    std::unordered_map<std::string_view, List::iterator> index_;
};

// LRU cache simulator: reads a capacity and a stream of commands from stdin
// and writes command results to stdout. See SPEC.md.

#include "lru_cache.hpp"

#include <charconv>
#include <cstddef>
#include <cstdio>
#include <iterator>
#include <string>
#include <string_view>

namespace {

// Reads the whole of `stream` in large chunks (much faster than iostreams).
std::string read_all(std::FILE* stream) {
    std::string data;
    std::size_t used = 0;
    constexpr std::size_t kChunk = std::size_t{1} << 16;
    for (;;) {
        data.resize(used + kChunk);
        const std::size_t got = std::fread(data.data() + used, 1, kChunk, stream);
        used += got;
        if (got < kChunk) {
            break;
        }
    }
    data.resize(used);
    return data;
}

// Splits `text` into lines on '\n', tolerating a missing final newline and
// stray '\r' before the newline.
class LineReader {
public:
    explicit LineReader(std::string_view text) : rest_(text) {}

    bool next(std::string_view& line) {
        if (rest_.empty()) {
            return false;
        }
        const auto nl = rest_.find('\n');
        line = rest_.substr(0, nl);
        rest_ = nl == std::string_view::npos ? std::string_view{} : rest_.substr(nl + 1);
        if (!line.empty() && line.back() == '\r') {
            line.remove_suffix(1);
        }
        return true;
    }

private:
    std::string_view rest_;
};

// Returns the next space-delimited token from `s`, advancing past it.
std::string_view next_token(std::string_view& s) {
    const auto start = s.find_first_not_of(' ');
    if (start == std::string_view::npos) {
        s = {};
        return {};
    }
    s.remove_prefix(start);
    const auto end = s.find(' ');
    const auto token = s.substr(0, end);
    s = end == std::string_view::npos ? std::string_view{} : s.substr(end);
    return token;
}

std::size_t parse_capacity(std::string_view line) {
    const auto token = next_token(line);
    std::size_t capacity = 0;
    std::from_chars(token.data(), token.data() + token.size(), capacity);
    return capacity;
}

void execute(LruCache& cache, std::string_view line, std::string& out) {
    const auto command = next_token(line);
    if (command == "SET") {
        const auto key = next_token(line);
        const auto value = next_token(line);
        if (!key.empty() && !value.empty()) {
            cache.set(key, value);
        }
    } else if (command == "GET") {
        if (const auto value = cache.get(next_token(line))) {
            out.append(*value);
        } else {
            out.append("NULL");
        }
        out.push_back('\n');
    } else if (command == "DEL") {
        out.append(cache.erase(next_token(line)) ? "1\n" : "0\n");
    } else if (command == "SIZE") {
        char buf[24];
        const auto [end, ec] = std::to_chars(std::begin(buf), std::end(buf), cache.size());
        out.append(buf, end);
        out.push_back('\n');
    }
    // Blank or unrecognised lines produce no output.
}

}  // namespace

int main() {
    const std::string input = read_all(stdin);
    LineReader lines(input);

    std::string_view line;
    if (!lines.next(line)) {
        return 0;
    }
    LruCache cache(parse_capacity(line));

    std::string out;
    out.reserve(1 << 20);
    while (lines.next(line)) {
        execute(cache, line, out);
    }

    std::fwrite(out.data(), 1, out.size(), stdout);
    std::fflush(stdout);
    return 0;
}
